mkdir -p /app/migrations
cat > /app/migrations/002_users_v2.sql <<'SQL'
PRAGMA foreign_keys=OFF;

-- Reassign orders of duplicate users to the kept user (lowest id per normalized email)
UPDATE orders SET user_id = (
  SELECT MIN(u2.id) FROM users u2
  WHERE lower(trim(u2.email)) = (SELECT lower(trim(u.email)) FROM users u WHERE u.id = orders.user_id)
)
WHERE EXISTS (SELECT 1 FROM users u WHERE u.id = orders.user_id);

-- Merge users with equal normalized email, keeping lowest id
DELETE FROM users WHERE id NOT IN (SELECT MIN(id) FROM users GROUP BY lower(trim(email)));

-- Rebuild users table to v2 schema
CREATE TABLE users_new(
  id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  signup_date TEXT NOT NULL
);

INSERT INTO users_new(id, first_name, last_name, email, signup_date)
SELECT
  id,
  CASE WHEN instr(trim(full_name), ' ') = 0 THEN trim(full_name) ELSE substr(trim(full_name), 1, instr(trim(full_name), ' ') - 1) END,
  CASE WHEN instr(trim(full_name), ' ') = 0 THEN '' ELSE trim(substr(trim(full_name), instr(trim(full_name), ' ') + 1)) END,
  lower(trim(email)),
  printf('%04d-%02d-%02d',
    CAST(substr(substr(trim(signup), instr(trim(signup), '/') + 1), instr(substr(trim(signup), instr(trim(signup), '/') + 1), '/') + 1) AS INTEGER),
    CAST(substr(trim(signup), 1, instr(trim(signup), '/') - 1) AS INTEGER),
    CAST(substr(substr(trim(signup), instr(trim(signup), '/') + 1), 1, instr(substr(trim(signup), instr(trim(signup), '/') + 1), '/') - 1) AS INTEGER)
  )
FROM users;

DROP TABLE users;
ALTER TABLE users_new RENAME TO users;

-- Bump schema version
INSERT OR IGNORE INTO meta(key, value) VALUES ('schema_version', '2');
UPDATE meta SET value = '2' WHERE key = 'schema_version';

PRAGMA foreign_keys=ON;
